/**
 * Battle field backgrounds: which scene a fight is drawn on and whether it is
 * day or night. Pure functions — no Angular, no DOM. The images live in
 * public/assets/backgrounds/ (generated by scripts/build-backgrounds.mjs).
 */

export type SceneId =
  | 'grass'
  | 'forest'
  | 'water'
  | 'beach'
  | 'city'
  | 'arena'
  | 'cave'
  | 'indoor'
  | 'elite-four';
export type TimeOfDay = 'day' | 'night';

export interface BattleBackground {
  scene: SceneId;
  time: TimeOfDay;
}

export interface SceneInfo {
  id: SceneId;
  /** German name shown in the custom-battle and debug pickers. */
  label: string;
  /** Outdoor scenes come in a day and a night version. */
  hasNight: boolean;
}

export const SCENES: readonly SceneInfo[] = [
  { id: 'grass', label: 'Wiese', hasNight: true },
  { id: 'forest', label: 'Wald', hasNight: true },
  { id: 'water', label: 'Auf dem Wasser', hasNight: true },
  { id: 'beach', label: 'Strand', hasNight: true },
  { id: 'city', label: 'Stadt', hasNight: true },
  { id: 'arena', label: 'Arena (draußen)', hasNight: true },
  { id: 'cave', label: 'Höhle', hasNight: false },
  { id: 'indoor', label: 'Halle', hasNight: false },
  { id: 'elite-four', label: 'Top-Vier-Halle', hasNight: false }
];

/** Scenes a random battle may roll. */
export const OUTDOOR_SCENES: readonly SceneId[] = SCENES.filter((s) => s.hasNight).map((s) => s.id);

export function isSceneId(v: unknown): v is SceneId {
  return SCENES.some((s) => s.id === v);
}

/** Night from 20:00 until 6:00 local time. */
export function timeOfDay(date: Date): TimeOfDay {
  const h = date.getHours();
  return h >= 20 || h < 6 ? 'night' : 'day';
}

/** A background; scenes without a night version always use day. */
export function background(scene: SceneId, time: TimeOfDay): BattleBackground {
  const hasNight = SCENES.find((s) => s.id === scene)?.hasNight ?? false;
  return { scene, time: hasNight ? time : 'day' };
}

export function randomOutdoorScene(rng: () => number = Math.random): SceneId {
  return OUTDOOR_SCENES[Math.floor(rng() * OUTDOOR_SCENES.length)];
}

const GYM_TYPE_SCENES: Record<string, SceneId> = {
  Water: 'water',
  Ice: 'water',
  Grass: 'forest',
  Bug: 'forest',
  Poison: 'forest',
  Rock: 'cave',
  Ground: 'cave',
  Steel: 'cave',
  Dragon: 'cave',
  Ghost: 'cave',
  Electric: 'city',
  Normal: 'city',
  Dark: 'city',
  Fighting: 'arena',
  Psychic: 'indoor',
  Fairy: 'indoor',
  Fire: 'indoor',
  Flying: 'grass'
};

/** Scene for a gym leader's speciality type ("Water"); unknown types get grass. */
export function sceneForGymType(type: string): SceneId {
  return GYM_TYPE_SCENES[type] ?? 'grass';
}

/** Asset path of a background image. */
export function backgroundUrl(bg: BattleBackground): string {
  const hasNight = SCENES.find((s) => s.id === bg.scene)?.hasNight ?? false;
  return `assets/backgrounds/${hasNight ? `${bg.scene}-${bg.time}` : bg.scene}.svg`;
}
